import http from 'http';
type Fn = (...a: any[]) => any;
function wrap(fn: Fn): any { return function (...a: any[]) { return fn(...a); }; }
async function main(): Promise<void> {
  const srv = http.createServer(wrap((req: any, res: any) => {
    if (req.url === '/a') { res.end(); } else if (req.url === '/b') { res.end(undefined); } else { res.end('x'); }
  }));
  await new Promise<void>((r) => srv.listen(0, '127.0.0.1', () => r()));
  const port = (srv.address() as any).port;
  const out: string[] = [];
  for (const p of ['/a', '/b', '/c']) {
    const r = await fetch('http://127.0.0.1:' + port + p);
    out.push(p + ':' + r.status + ':' + JSON.stringify(await r.text()));
  }
  console.log(out.join(','));
  srv.close();
}
